(async () => {
// Explanation Lab integration - generated by the Study Console.
const { default: createExplanationLabClient } = await import("./explanation-lab-client.js");
const explanationLab = await createExplanationLabClient();
const assignedCondition = explanationLab.launch.condition;
window.EXPLANATION_LAB_CONDITION = assignedCondition;
window.explanationLab = explanationLab;
const explanationLabStudyStartedAt = performance.now();
(function () {
  "use strict";

  function completionScreen(jsPsych) {
    const row = window.fossilPilotResult || jsPsych.data.get().last(1).values()[0] || {};
    const target = document.getElementById("jspsych-target");
    target.innerHTML = '<main class="completion-screen"><section>' +
      '<span class="completion-mark" aria-hidden="true">✓</span>' +
      '<small>Single trial complete</small>' +
      '<h1>Your responses were recorded.</h1>' +
      '<p>You rated <strong>' + (row.focal_fossil_label || "the fossil sample") + '</strong> as <strong>' +
        (row.new_species_extent_rating == null ? "—" : row.new_species_extent_rating) + ' out of 100</strong>.</p>' +
      '<button type="button" data-review-trial>Review the trial again</button>' +
      '<span class="prototype-note">Sandbox test complete · Responses saved to the Explanation Lab</span>' +
    '</section></main>';
    target.querySelector("[data-review-trial]").addEventListener("click", function () { window.location.reload(); });
  }

  function boot() {
    try {
      window.FossilPilot.Stimuli.validate();
      const jsPsych = initJsPsych({
        display_element: "jspsych-target",
        on_finish: async function () {
    await explanationLab.submitAndRedirect(jsPsych.data.get(), {
      durationMs: performance.now() - explanationLabStudyStartedAt,
      metadata: {
        experimentVersion: "fossil_pilot_v27",
        schemaVersion: "2.0.0",
        demographicFields: ["age","ethnicity","gender","other_gender","other_race","race"]
      }
    });
 completionScreen(jsPsych); }
      });
      window.fossilPilotJsPsych = jsPsych;
      jsPsych.run([
        { type: window.FossilConsentPlugin },
        { type: window.FossilStudyIntroductionPlugin },
        { type: window.FossilSpeciationTrialPlugin },
        { type: window.FossilDemographicsPlugin }
      ]);
    } catch (error) {
      console.error("Fossil Pilot initialization error", error);
      document.getElementById("jspsych-target").innerHTML = '<main class="completion-screen error-screen"><section><h1>The trial could not be opened.</h1><p>Please reopen index.html from the complete pilot_v27 folder.</p></section></main>';
    }
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();
})();

})().catch((error) => {
  console.error("Explanation Lab startup failed", error);
  const main = document.createElement("main");
  main.setAttribute("role", "alert");
  main.style.cssText = "max-width:720px;margin:12vh auto;padding:32px;border:1px solid #d8cfca;border-radius:14px;font:16px/1.55 system-ui,sans-serif;background:#fff;color:#222";
  const title = document.createElement("h1");
  title.textContent = "This study is not accepting responses yet";
  const detail = document.createElement("p");
  detail.textContent = error instanceof Error ? error.message : "The study could not be opened. Please return to Prolific and contact the researcher.";
  main.append(title, detail);
  document.body.replaceChildren(main);
});